package com.glowingfederal.worldeditoverdrive.snapshot;
import com.sk89q.worldedit.Vector;import com.sk89q.worldedit.blocks.BaseBlock;import com.sk89q.worldedit.extent.Extent;import java.util.Collections;import java.util.HashMap;import java.util.Map;
/** Immutable, chunk-local destination state published only after bounded server-thread capture. */
public final class DestinationRegionSnapshot {private final Map<Long,ChunkStateSnapshot> chunks;private DestinationRegionSnapshot(Map<Long,ChunkStateSnapshot> chunks){this.chunks=Collections.unmodifiableMap(chunks);}public BaseBlock getBlock(int x,int y,int z){ChunkStateSnapshot c=chunks.get(Long.valueOf(key(x>>4,z>>4)));return c==null?null:c.get(x,y,z);}public int chunkCount(){return chunks.size();}private static long key(int x,int z){return((long)x<<32)^(z&0xffffffffL);}
 public static final class Capture{private final Extent extent;private final int minX,minY,minZ,maxX,maxY,maxZ;private final Map<Long,ChunkStateSnapshot.Builder> chunks=new HashMap<Long,ChunkStateSnapshot.Builder>();private int x,y,z;private boolean complete;public Capture(Extent extent,Vector min,Vector max,int halo){this.extent=extent;minX=min.getBlockX()-halo;minY=min.getBlockY()-halo;minZ=min.getBlockZ()-halo;maxX=max.getBlockX()+halo;maxY=max.getBlockY()+halo;maxZ=max.getBlockZ()+halo;x=minX;y=minY;z=minZ;}public int captureUntil(long deadline){int read=0;while(!complete&&System.nanoTime()<deadline){BaseBlock block=extent.getBlock(new Vector(x,y,z));long key=key(x>>4,z>>4);ChunkStateSnapshot.Builder b=chunks.get(Long.valueOf(key));if(b==null){b=new ChunkStateSnapshot.Builder();chunks.put(Long.valueOf(key),b);}b.put(x,y,z,block);read++;advance();}return read;}private void advance(){if(++x<=maxX)return;x=minX;if(++z<=maxZ)return;z=minZ;if(++y<=maxY)return;complete=true;}public boolean isComplete(){return complete;}public DestinationRegionSnapshot publish(){if(!complete)throw new IllegalStateException("snapshot capture incomplete");Map<Long,ChunkStateSnapshot> ready=new HashMap<Long,ChunkStateSnapshot>();for(Map.Entry<Long,ChunkStateSnapshot.Builder> e:chunks.entrySet())ready.put(e.getKey(),e.getValue().build());return new DestinationRegionSnapshot(ready);}}
}
